mapper.select:
/* PT 프로젝트 목록 조회 proposal.selectPtProjectList */ SELECT p.PT_PROJECT_ID AS PT_PROJECT_ID , p.PROJECT_NM AS PROJECT_NM , p.ORG_NM AS ORG_NM , p.TARGET_TYPE_CD AS TARGET_TYPE_CD , DATE_FORMAT(p.DUE_DT, '%Y-%m-%d') AS DUE_DT , p.STATUS_CD AS STATUS_CD , cd.CODE_NM AS STATUS_NM , DATE_FORMAT(p.CREATE_DT, '%Y-%m-%d %H:%i:%s') AS CREATE_DT , DATE_FORMAT(p.MODIFY_DT, '%Y-%m-%d %H:%i:%s') AS MODIFY_DT , p.CREATE_USER_ID AS CREATE_USER_ID , CASE WHEN p.WRITING_GUIDELINE_JSON IS NOT NULL THEN 'Y' ELSE 'N' END AS STAGE1_DONE_YN FROM TB_PT_PROJECT p LEFT JOIN TB_CODE cd ON cd.CODE_GRP_ID = 'PT000002' AND cd.CODE_ID = p.STATUS_CD WHERE 1 = 1
AND p.STATUS_CD = #{statusCd}
AND ( p.PROJECT_NM LIKE CONCAT('%', #{keyword}, '%') OR p.ORG_NM LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY p.MODIFY_DT DESC, p.CREATE_DT DESC
LIMIT #{limit}
OFFSET #{offset}

mapper.update:
/* 채팅 로그 PT 프로젝트 참조 업데이트 proposal.updateChatLogRef */
UPDATE TB_CHAT_LOG
SET
    SVC_TY  = 'D'
    , REF_ID  = #{ptProjectId}
WHERE LOG_ID = #{logId}

/* PT 프로젝트 Stage2 진행 상태 업데이트 proposal.updateStage2StatusCd */
UPDATE TB_PT_PROJECT
SET
    STAGE2_STATUS_CD = #{stage2StatusCd}
    , MODIFY_DT = NOW()
    , MODIFY_USER_ID = #{modifyUserId}
WHERE PT_PROJECT_ID = #{ptProjectId}

/* PT 프로젝트 최대 단계 번호 업데이트 proposal.updateMaxStepNo */
UPDATE TB_PT_PROJECT
SET
    MAX_STEP_NO = GREATEST(COALESCE(MAX_STEP_NO, 0), #{maxStepNo})
    , MODIFY_DT = NOW()
    , MODIFY_USER_ID = #{modifyUserId}
WHERE PT_PROJECT_ID = #{ptProjectId}

/* PT 프로젝트 상태 업데이트 proposal.updateProjectStatus */
UPDATE TB_PT_PROJECT
SET
    STATUS_CD  = #{statusCd}
    , MODIFY_DT = NOW()
    , MODIFY_USER_ID = #{modifyUserId}
WHERE PT_PROJECT_ID = #{ptProjectId}

/* PT 프로젝트 작성지침 JSON 업데이트 proposal.updateProjectWritingGuideline */
UPDATE TB_PT_PROJECT
SET
    WRITING_GUIDELINE_JSON = #{writingGuidelineJson}
    , MODIFY_DT = NOW()
    , MODIFY_USER_ID = #{modifyUserId}
WHERE PT_PROJECT_ID = #{ptProjectId}

/* PT 프로젝트 제안 구분(TARGET_TYPE_CD) 업데이트 proposal.updateProjectTargetType */
UPDATE TB_PT_PROJECT
SET
    TARGET_TYPE_CD = #{targetTypeCd}
    , MODIFY_DT = NOW()
    , MODIFY_USER_ID = #{modifyUserId}
WHERE PT_PROJECT_ID = #{ptProjectId}

