mapper.insert:
/* PT 요구사항 등록 proposal.insertRequirement */
INSERT INTO TB_PT_REQUIREMENT (
    REQUIREMENT_ID
    , PT_PROJECT_ID
    , REQ_NO
    , REQ_CATEGORY_TXT
    , REQ_CONTENT
    , REQ_DETAIL_TXT
    , MANDATORY_YN
    , SOURCE_TYPE_CD
    , CONFIRM_NEEDED_YN
    , SORT_ORD
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{requirementId}
    , #{ptProjectId}
    , #{reqNo}
    , #{reqCategoryTxt}
    , #{reqContent}
    , #{reqDetailTxt}
    , COALESCE(#{mandatoryYn}, 'Y')
    , COALESCE(#{sourceTypeCd}, '001')
    , COALESCE(#{confirmNeededYn}, 'N')
    , COALESCE(#{sortOrd}, 0)
    , #{createUserId}
    , NOW()
)

