CORE_MESSAGE = #{coreMessage}, CUSTOMER_PROBLEM = #{customerProblem}, PROPOSAL_STRATEGY = #{proposalStrategy}, EVIDENCE = #{evidence}, EXPECTED_EFFECT = #{expectedEffect}, DIFFERENTIATION = #{differentiation}, SOURCE_PROBLEM_IDS_JSON = #{sourceProblemIdsJson}, MODIFY_DT = NOW(), MODIFY_USER_ID = #{modifyUserId}
