mapper.update:
/* Stage2 TOC 매핑 업데이트 — 값 변경 시에만 호출 (MODIFY_DT 갱신 → Step6 stale 판별) proposal.updateTocEvalLinkAndReqIds */
UPDATE TB_PT_TOC
SET LINKED_EVAL_CRITERIA_ID = #{linkedEvalCriteriaId, jdbcType=VARCHAR},
    COVERED_REQ_IDS_JSON    = #{coveredReqIdsJson, jdbcType=VARCHAR},
    PLANNED_SLIDE_CNT       = #{plannedSlideCnt},
    MODIFY_DT               = NOW()
    , MODIFY_USER_ID = #{modifyUserId}
WHERE TOC_ID = #{tocId}

/* 전략검토 수동 TOC 매핑 — plannedSlideCnt 유지 proposal.updateTocMappingUser */
UPDATE TB_PT_TOC
SET LINKED_EVAL_CRITERIA_ID = #{linkedEvalCriteriaId, jdbcType=VARCHAR},
    COVERED_REQ_IDS_JSON    = #{coveredReqIdsJson, jdbcType=VARCHAR},
    MODIFY_DT               = NOW()
    , MODIFY_USER_ID = #{modifyUserId}
WHERE TOC_ID = #{tocId}

