mapper.select:
/* 형제 소목차 완료 슬라이드 제목 조회 (중복 방지 컨텍스트용) proposal.selectSiblingSlides */
SELECT s.TITLE_TXT, s.EYEBROW_TXT, s.HIGHLIGHT_BANNER_TXT, t.SECTION_NM
FROM TB_PT_SLIDE s
JOIN TB_PT_TOC t ON s.TOC_ID = t.TOC_ID
WHERE t.PARENT_TOC_ID = #{parentTocId}
  AND t.TOC_ID != #{currentTocId}
  AND s.RENDER_STATUS_CD = '003'
ORDER BY t.SORT_ORD, s.SLIDE_NO
LIMIT 10

/* 프로젝트 최대 SLIDE_NO 조회 proposal.selectMaxSlideNo */
SELECT COALESCE(MAX(SLIDE_NO), 0)
FROM TB_PT_SLIDE
WHERE PT_PROJECT_ID = #{ptProjectId}

mapper.update:
/* 슬라이드 수정 proposal.updateSlide */ UPDATE TB_PT_SLIDE
LAYOUT_TYPE_CD = #{layoutType}, REQ_IDS_JSON = #{reqIdsJson}, EYEBROW_TXT = #{eyebrowTxt}, TITLE_TXT = #{titleTxt}, SUBTITLE_TXT = #{subtitleTxt}, HIGHLIGHT_BANNER_TXT = #{highlightBannerTxt}, COMPONENTS_JSON = #{componentsJson}, STEP_FLOW_BAR_JSON = #{stepFlowBarJson}, CONCLUSION_RIBBON_TXT = #{conclusionRibbonTxt}, IMAGE_GEN_HINT = #{imageGenHint}, RENDERED_IMAGE_PATH = #{renderedImagePath}, COMPOSITE_IMAGE_PATH = #{compositeImagePath}, RENDER_STATUS_CD = #{renderStatusCd}, MODIFY_USER_ID = #{modifyUserId}, MODIFY_DT = NOW()
WHERE SLIDE_ID = #{slideId}

/* 소목차 목표 슬라이드 수 단건 수정 proposal.updateTocPlannedSlideCnt */
UPDATE TB_PT_TOC
SET PLANNED_SLIDE_CNT = #{plannedSlideCnt},
    MODIFY_DT         = NOW()
    , MODIFY_USER_ID = #{modifyUserId}
WHERE TOC_ID = #{tocId}

mapper.select:
/* 소목차 정식 슬라이드 수 조회 (005=스테이징 제외) proposal.countNonStagingSlidesByToc */
