WHERE TOC_ID = #{tocId}
  AND RENDER_STATUS_CD = '005'

mapper.update:
/* 소목차 스테이징 슬라이드를 완료 상태로 승격 proposal.promoteStagingSlidesByToc */
UPDATE TB_PT_SLIDE
