mapper.select:
/* 스텝 프롬프트 목록 조회 (STAGE_CD 기준) proposal.selectStepPrompts */ SELECT A.PROMPT_ID AS PROMPT_ID , A.PROMPT_NAME AS PROMPT_NAME , A.CONTENT AS CONTENT , A.ORIGINAL_CONTENT AS ORIGINAL_CONTENT , B.STAGE_CD AS STAGE_CD FROM TB_PROMPT A LEFT JOIN TB_PROMPT_APPLY_AGT B ON B.PROMPT_ID = A.PROMPT_ID AND B.APPLY_YN = 'Y' WHERE A.USE_YN = 'Y' AND B.STAGE_CD IN
#{stageCd}
ORDER BY B.STAGE_CD

mapper.update:
/* 스텝 프롬프트 내용 수정 proposal.updatePromptContent */
UPDATE TB_PROMPT
SET CONTENT = #{content}
WHERE PROMPT_ID = #{promptId}

/* 스텝 프롬프트 원본 복구 (CONTENT = ORIGINAL_CONTENT) proposal.restorePromptContent */
UPDATE TB_PROMPT
SET CONTENT = ORIGINAL_CONTENT
WHERE PROMPT_ID = #{promptId}
